ALTER TABLE dbo.users WITH CHECK ADD CONSTRAINT [ck_users_role] CHECK ([role]='staff' OR [role]='admin');
ALTER TABLE dbo.pois WITH CHECK ADD CONSTRAINT [ck_pois_latitude] CHECK ([latitude]>=(-90) AND [latitude]<=(90));
ALTER TABLE dbo.pois WITH CHECK ADD CONSTRAINT [ck_pois_longitude] CHECK ([longitude]>=(-180) AND [longitude]<=(180));
ALTER TABLE dbo.poi_images WITH CHECK ADD CONSTRAINT [ck_poi_images_size] CHECK (datalength([content])>=(1) AND datalength([content])<=(5242880));
ALTER TABLE dbo.poi_images WITH CHECK ADD CONSTRAINT [ck_poi_images_content_type] CHECK ([content_type]='image/webp' OR [content_type]='image/png' OR [content_type]='image/jpeg');
ALTER TABLE dbo.users WITH CHECK ADD CONSTRAINT [ck_users_status] CHECK ([status]='disabled' OR [status]='active');
ALTER TABLE dbo.usage_events WITH CHECK ADD CONSTRAINT [ck_usage_events_type] CHECK ([event_type]='route_created' OR [event_type]='audio_end' OR [event_type]='audio_pause' OR [event_type]='audio_start' OR [event_type]='poi_view');
ALTER TABLE dbo.system_logs WITH CHECK ADD CONSTRAINT [ck_system_logs_level] CHECK ([level]='error' OR [level]='warning' OR [level]='info');
